-- Test the exact polygon from API logs
select * from core.pois_in_polygon('POLYGON((2.1521127128194673 41.36856482755874, 2.1542584800313813 41.36941830324104, 2.1551597022603852 41.367952894706434, 2.1530073113298176 41.367216579274384, 2.1521127128194673 41.36856482755874))');

-- Compare with your successful polygon
select * from core.pois_in_polygon('POLYGON((2.1521 41.3686, 2.1542 41.3694, 2.1551 41.3679, 2.1532 41.3671, 2.1521 41.3686))');

-- Check which POIs are in the area
SELECT attraction_id, latitude, longitude
FROM core.attraction_coordinate
WHERE longitude BETWEEN 2.151 AND 2.156
  AND latitude BETWEEN 41.367 AND 41.370;

-- Manually check if POIs are inside the API polygon
-- POI 1: 92fb7ce6-8712-4512-99a9-d568c043b22a (41.3684399, 2.15357)
-- POI 2: 1861d160-df15-4931-8399-bb3ad95b1643 (41.3677819, 2.1541013)
-- POI 3: 11466e21-a912-447d-9af7-18528f4d1814 (41.3698842, 2.1556915)

-- Test with individual points
SELECT ST_Within(
  ST_SetSRID(ST_MakePoint(2.15357, 41.3684399), 4326),
  ST_GeomFromText('POLYGON((2.1521127128194673 41.36856482755874, 2.1542584800313813 41.36941830324104, 2.1551597022603852 41.367952894706434, 2.1530073113298176 41.367216579274384, 2.1521127128194673 41.36856482755874))', 4326)
) as poi1_inside;

SELECT ST_Within(
  ST_SetSRID(ST_MakePoint(2.1541013, 41.3677819), 4326),
  ST_GeomFromText('POLYGON((2.1521127128194673 41.36856482755874, 2.1542584800313813 41.36941830324104, 2.1551597022603852 41.367952894706434, 2.1530073113298176 41.367216579274384, 2.1521127128194673 41.36856482755874))', 4326)
) as poi2_inside;

SELECT ST_Within(
  ST_SetSRID(ST_MakePoint(2.1556915, 41.3698842), 4326),
  ST_GeomFromText('POLYGON((2.1521127128194673 41.36856482755874, 2.1542584800313813 41.36941830324104, 2.1551597022603852 41.367952894706434, 2.1530073113298176 41.367216579274384, 2.1521127128194673 41.36856482755874))', 4326)
) as poi3_inside; 